/// Set e to a square root of x. If x is not a square, p384Sqrt returns
/// false and e is unchanged. e and x can overlap.
fn p384Sqrt(e: &mut P384Element, x: P384Element) -> bool {
    let mut candidate = P384Element::New();
    p384SqrtCandidate(&mut candidate, x);
    let mut square = P384Element::New();
    square.Square(candidate);
    if square.Equal(x) != 1 {
        return false;
    }
    e.Set(candidate);
    return true;
}

